const pptxgen = require("pptxgenjs");

// ============================================================
// CONFIGURATION
// ============================================================
const COLORS = {
  primary: "1E2761",      // Midnight Executive navy
  secondary: "CADCFC",    // Ice blue
  accent: "FFFFFF",       // White
  dark: "0F172A",         // Near black
  slate: "334155",        // Slate
  muted: "64748B",        // Muted text
  lightBg: "F8FAFC",      // Light background
  cardBg: "FFFFFF",       // Card background
  chartBar: "1E2761",     // Chart bar color
  chartBar2: "3B82F6",    // Chart secondary
  chartBar3: "60A5FA",    // Chart tertiary
  highlight: "F59E0B",    // Amber highlight
};

const FONTS = {
  header: "Calibri",
  body: "Calibri Light",
};

const pres = new pptxgen();
pres.layout = "LAYOUT_16x9";
pres.author = "Stack Overflow Survey Analysis";
pres.title = "Developer Workforce & Compensation Trends — 2024 Stack Overflow Survey";
pres.subject = "Developer compensation and workforce trends";

// ============================================================
// HELPERS
// ============================================================
function addFooter(slide, text = "Source: Stack Overflow Developer Survey 2024") {
  slide.addText(text, {
    x: 0.5, y: 5.35, w: 9, h: 0.2,
    fontSize: 9, fontFace: FONTS.body, color: COLORS.muted,
    align: "left", valign: "middle",
  });
}

function addSlideNumber(slide, num) {
  slide.addText(String(num), {
    x: 9.2, y: 5.35, w: 0.3, h: 0.2,
    fontSize: 9, fontFace: FONTS.body, color: COLORS.muted,
    align: "right", valign: "middle",
  });
}

// ============================================================
// SLIDE 1: TITLE SLIDE
// ============================================================
{
  const slide = pres.addSlide();
  slide.background = { color: COLORS.primary };

  // Decorative shape
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 10, h: 5.625,
    fill: { color: COLORS.primary },
  });

  // Accent bar left
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 1.8, w: 0.08, h: 2.2,
    fill: { color: COLORS.secondary },
  });

  slide.addText("Developer Workforce & Compensation Trends", {
    x: 0.8, y: 1.7, w: 8.5, h: 0.9,
    fontSize: 40, fontFace: FONTS.header, color: COLORS.accent,
    bold: true, align: "left", valign: "middle",
    margin: 0,
  });

  slide.addText("2024 Stack Overflow Survey", {
    x: 0.8, y: 2.5, w: 8.5, h: 0.5,
    fontSize: 28, fontFace: FONTS.header, color: COLORS.secondary,
    align: "left", valign: "middle",
    margin: 0,
  });

  slide.addText("65,437 respondents across 180+ countries", {
    x: 0.8, y: 3.2, w: 8.5, h: 0.4,
    fontSize: 16, fontFace: FONTS.body, color: COLORS.accent,
    align: "left", valign: "middle",
    margin: 0,
  });

  slide.addText("Source: survey.stackoverflow.co/2024/work", {
    x: 0.8, y: 5.0, w: 8.5, h: 0.3,
    fontSize: 11, fontFace: FONTS.body, color: COLORS.secondary,
    align: "left", valign: "middle",
    margin: 0,
  });
}

// ============================================================
// SLIDE 2: EMPLOYMENT STATUS OVERVIEW
// ============================================================
{
  const slide = pres.addSlide();
  slide.background = { color: COLORS.lightBg };

  slide.addText("84% of Developers Are Working, but Full-Time Employment Dips in the U.S.", {
    x: 0.5, y: 0.35, w: 9, h: 0.7,
    fontSize: 28, fontFace: FONTS.header, color: COLORS.primary,
    bold: true, align: "left", valign: "middle",
    margin: 0,
  });

  // Left: key stats
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 1.3, w: 3.0, h: 1.1,
    fill: { color: COLORS.cardBg },
    shadow: { type: "outer", color: "000000", blur: 6, offset: 2, angle: 135, opacity: 0.08 },
  });
  slide.addText("69%", {
    x: 0.7, y: 1.4, w: 2.6, h: 0.5,
    fontSize: 36, fontFace: FONTS.header, color: COLORS.primary,
    bold: true, align: "left", valign: "middle",
    margin: 0,
  });
  slide.addText("Full-time employment (global)", {
    x: 0.7, y: 1.85, w: 2.6, h: 0.4,
    fontSize: 12, fontFace: FONTS.body, color: COLORS.slate,
    align: "left", valign: "middle",
    margin: 0,
  });

  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 2.6, w: 3.0, h: 1.1,
    fill: { color: COLORS.cardBg },
    shadow: { type: "outer", color: "000000", blur: 6, offset: 2, angle: 135, opacity: 0.08 },
  });
  slide.addText("16.4%", {
    x: 0.7, y: 2.7, w: 2.6, h: 0.5,
    fontSize: 36, fontFace: FONTS.header, color: COLORS.primary,
    bold: true, align: "left", valign: "middle",
    margin: 0,
  });
  slide.addText("Independent contracting / freelancing", {
    x: 0.7, y: 3.15, w: 2.6, h: 0.4,
    fontSize: 12, fontFace: FONTS.body, color: COLORS.slate,
    align: "left", valign: "middle",
    margin: 0,
  });

  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 3.9, w: 3.0, h: 1.1,
    fill: { color: COLORS.cardBg },
    shadow: { type: "outer", color: "000000", blur: 6, offset: 2, angle: 135, opacity: 0.08 },
  });
  slide.addText("13.2%", {
    x: 0.7, y: 4.0, w: 2.6, h: 0.5,
    fontSize: 36, fontFace: FONTS.header, color: COLORS.primary,
    bold: true, align: "left", valign: "middle",
    margin: 0,
  });
  slide.addText("Full-time students", {
    x: 0.7, y: 4.45, w: 2.6, h: 0.4,
    fontSize: 12, fontFace: FONTS.body, color: COLORS.slate,
    align: "left", valign: "middle",
    margin: 0,
  });

  // Right: bar chart global vs US full-time
  slide.addChart(pres.charts.BAR, [
    { name: "Global", labels: ["Full-time", "Freelance", "Student"], values: [69, 16.4, 13.2] },
    { name: "U.S. 2024", labels: ["Full-time", "Freelance", "Student"], values: [64.8, null, null] },
  ], {
    x: 4.0, y: 1.2, w: 5.5, h: 3.8,
    barDir: "col", barGrouping: "clustered",
    chartColors: [COLORS.primary, COLORS.chartBar3],
    chartArea: { fill: { color: COLORS.cardBg }, roundedCorners: true },
    catAxisLabelColor: COLORS.slate,
    valAxisLabelColor: COLORS.slate,
    valGridLine: { color: "E2E8F0", size: 0.5 },
    catGridLine: { style: "none" },
    showValue: true,
    dataLabelPosition: "outEnd",
    dataLabelColor: COLORS.slate,
    showLegend: true,
    legendPos: "b",
    title: "Employment Status: Global vs U.S. Full-time",
    titleFontSize: 12,
    titleColor: COLORS.slate,
    valAxisMaxVal: 80,
  });

  // Context text below chart
  slide.addText("U.S. full-time employment dropped from 69% in 2023 to 64.8% in 2024. In the U.K. and Ukraine, non-full-time respondents lean toward independent contracting; in Germany and India, they are more likely to be students.", {
    x: 4.0, y: 4.95, w: 5.5, h: 0.5,
    fontSize: 10, fontFace: FONTS.body, color: COLORS.muted,
    align: "left", valign: "top",
    margin: 0,
  });

  addFooter(slide);
  addSlideNumber(slide, 2);
}

// ============================================================
// SLIDE 3: WORK ENVIRONMENT SHIFT
// ============================================================
{
  const slide = pres.addSlide();
  slide.background = { color: COLORS.lightBg };

  slide.addText("In-Person Work Rises to 20% While Hybrid Holds Steady at 42%", {
    x: 0.5, y: 0.35, w: 9, h: 0.7,
    fontSize: 28, fontFace: FONTS.header, color: COLORS.primary,
    bold: true, align: "left", valign: "middle",
    margin: 0,
  });

  // Chart: 3-year trend
  slide.addChart(pres.charts.BAR, [
    { name: "Remote", labels: ["2022", "2023", "2024"], values: [null, null, 38] },
    { name: "Hybrid", labels: ["2022", "2023", "2024"], values: [null, 42, 42] },
    { name: "In-person", labels: ["2022", "2023", "2024"], values: [15, 16, 20] },
  ], {
    x: 0.5, y: 1.2, w: 6.0, h: 3.8,
    barDir: "col", barGrouping: "clustered",
    chartColors: ["3B82F6", "1E2761", "F59E0B"],
    chartArea: { fill: { color: COLORS.cardBg }, roundedCorners: true },
    catAxisLabelColor: COLORS.slate,
    valAxisLabelColor: COLORS.slate,
    valGridLine: { color: "E2E8F0", size: 0.5 },
    catGridLine: { style: "none" },
    showValue: true,
    dataLabelPosition: "outEnd",
    dataLabelColor: COLORS.slate,
    showLegend: true,
    legendPos: "b",
    title: "Work Environment Trends (2022–2024)",
    titleFontSize: 12,
    titleColor: COLORS.slate,
    valAxisMaxVal: 50,
  });

  // Right side: callout cards
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 6.8, y: 1.3, w: 2.7, h: 1.6,
    fill: { color: COLORS.cardBg },
    shadow: { type: "outer", color: "000000", blur: 6, offset: 2, angle: 135, opacity: 0.08 },
  });
  slide.addText("42%", {
    x: 7.0, y: 1.45, w: 2.3, h: 0.6,
    fontSize: 36, fontFace: FONTS.header, color: COLORS.primary,
    bold: true, align: "left", valign: "middle",
    margin: 0,
  });
  slide.addText("Hybrid — most common arrangement, unchanged from 2023", {
    x: 7.0, y: 2.05, w: 2.3, h: 0.7,
    fontSize: 12, fontFace: FONTS.body, color: COLORS.slate,
    align: "left", valign: "top",
    margin: 0,
  });

  slide.addShape(pres.shapes.RECTANGLE, {
    x: 6.8, y: 3.1, w: 2.7, h: 1.6,
    fill: { color: COLORS.cardBg },
    shadow: { type: "outer", color: "000000", blur: 6, offset: 2, angle: 135, opacity: 0.08 },
  });
  slide.addText("+5pp", {
    x: 7.0, y: 3.25, w: 2.3, h: 0.6,
    fontSize: 36, fontFace: FONTS.header, color: COLORS.highlight,
    bold: true, align: "left", valign: "middle",
    margin: 0,
  });
  slide.addText("In-person growth since 2022 (15% → 20%), third consecutive yearly rise", {
    x: 7.0, y: 3.85, w: 2.3, h: 0.7,
    fontSize: 12, fontFace: FONTS.body, color: COLORS.slate,
    align: "left", valign: "top",
    margin: 0,
  });

  addFooter(slide);
  addSlideNumber(slide, 3);
}

// ============================================================
// SLIDE 4: SALARY BY DEVELOPER TYPE (horizontal bar chart)
// ============================================================
{
  const slide = pres.addSlide();
  slide.background = { color: COLORS.lightBg };

  slide.addText("Senior Executives and Dev Advocates Top $124K+ Median Salary", {
    x: 0.5, y: 0.35, w: 9, h: 0.7,
    fontSize: 28, fontFace: FONTS.header, color: COLORS.primary,
    bold: true, align: "left", valign: "middle",
    margin: 0,
  });

  // Horizontal bar chart: top 10 roles (exclude Student for top 10 professional)
  // Using all 11 but sorted descending; we show top 10 excluding Student
  const roles = [
    "Senior Executive", "Dev Advocate", "Manager", "Dev Experience",
    "SRE", "Cloud Infra. Engineer", "Blockchain", "Product Manager",
    "Full-stack", "Front-end"
  ];
  const salaries = [127388, 124203, 115999, 109483, 99099, 96666, 85925, 80000, 63333, 48787];

  slide.addChart(pres.charts.BAR, [
    { name: "Median Salary (USD)", labels: roles, values: salaries },
  ], {
    x: 0.5, y: 1.1, w: 9, h: 3.9,
    barDir: "bar", // horizontal
    barGrouping: "clustered",
    chartColors: [COLORS.primary],
    chartArea: { fill: { color: COLORS.cardBg }, roundedCorners: true },
    catAxisLabelColor: COLORS.slate,
    valAxisLabelColor: COLORS.slate,
    valGridLine: { color: "E2E8F0", size: 0.5 },
    catGridLine: { style: "none" },
    showValue: true,
    dataLabelPosition: "outEnd",
    dataLabelColor: COLORS.slate,
    dataLabelFormat: "$#,##0",
    showLegend: false,
    title: "Median Annual Compensation by Developer Type (USD)",
    titleFontSize: 12,
    titleColor: COLORS.slate,
    catAxisLabelFontSize: 10,
  });

  slide.addText("Source: 22,677 salary responses (34.7% response rate). Reference: figure_1.jpg", {
    x: 0.5, y: 5.05, w: 9, h: 0.25,
    fontSize: 10, fontFace: FONTS.body, color: COLORS.muted,
    align: "left", valign: "middle",
    margin: 0,
  });

  addFooter(slide);
  addSlideNumber(slide, 4);
}

// ============================================================
// SLIDE 5: EXPERIENCE VS. SALARY (scatter plot)
// ============================================================
{
  const slide = pres.addSlide();
  slide.background = { color: COLORS.lightBg };

  slide.addText("Experience Pays: Top Roles Combine 14+ Years with Six-Figure Salaries", {
    x: 0.5, y: 0.35, w: 9, h: 0.7,
    fontSize: 28, fontFace: FONTS.header, color: COLORS.primary,
    bold: true, align: "left", valign: "middle",
    margin: 0,
  });

  // Scatter: x = avg years exp, y = median salary, name = developer type
  const scatterData = [
    { name: "Senior Executive", x: 17, y: 127388 },
    { name: "Dev Advocate", x: 16, y: 124203 },
    { name: "Manager", x: 15, y: 115999 },
    { name: "Dev Experience", x: 12, y: 109483 },
    { name: "SRE", x: 10, y: 99099 },
    { name: "Cloud Infra. Engineer", x: 13, y: 96666 },
    { name: "Blockchain", x: 9, y: 85925 },
    { name: "Product Manager", x: 14, y: 80000 },
    { name: "Full-stack", x: 10, y: 63333 },
    { name: "Front-end", x: 8, y: 48787 },
    { name: "Student", x: 2, y: 15466 },
  ];

  // PptxGenJS scatter expects array of {name, labels:[], values:[{x,y}]} ?
  // Actually per docs: scatter uses array of objects with x and y
  // Let's format correctly for pptxgenjs scatter chart
  const series = scatterData.map(pt => ({
    name: pt.name,
    labels: [pt.name],
    values: [{ x: pt.x, y: pt.y }],
  }));

  slide.addChart(pres.charts.SCATTER, series, {
    x: 0.5, y: 1.1, w: 9, h: 3.9,
    chartColors: [
      "1E2761", "3B82F6", "60A5FA", "93C5FD", "F59E0B",
      "EF4444", "10B981", "8B5CF6", "EC4899", "14B8A6", "64748B"
    ],
    chartArea: { fill: { color: COLORS.cardBg }, roundedCorners: true },
    catAxisLabelColor: COLORS.slate,
    valAxisLabelColor: COLORS.slate,
    valGridLine: { color: "E2E8F0", size: 0.5 },
    catGridLine: { style: "none" },
    showLegend: false,
    lineDataSymbol: "circle",
    lineDataSymbolSize: 10,
    showValue: false,
    catAxisTitle: "Average Years of Experience",
    catAxisTitleFontSize: 10,
    catAxisTitleColor: COLORS.slate,
    valAxisTitle: "Median Salary (USD)",
    valAxisTitleFontSize: 10,
    valAxisTitleColor: COLORS.slate,
    valAxisLabelFormat: "$#,##0",
    title: "Median Salary vs. Average Experience by Developer Type",
    titleFontSize: 12,
    titleColor: COLORS.slate,
  });

  slide.addText("Reference: figure_2.jpg. Senior roles cluster in the upper-right; Student is a clear outlier at $15K / ~2 years.", {
    x: 0.5, y: 5.05, w: 9, h: 0.25,
    fontSize: 10, fontFace: FONTS.body, color: COLORS.muted,
    align: "left", valign: "middle",
    margin: 0,
  });

  addFooter(slide);
  addSlideNumber(slide, 5);
}

// ============================================================
// SLIDE 6: SALARY BY LANGUAGE (scatter plot)
// ============================================================
{
  const slide = pres.addSlide();
  slide.background = { color: COLORS.lightBg };

  slide.addText("Erlang & Clojure Developers Earn >$95K; Dart & Prolog Below $45K", {
    x: 0.5, y: 0.35, w: 9, h: 0.7,
    fontSize: 28, fontFace: FONTS.header, color: COLORS.primary,
    bold: true, align: "left", valign: "middle",
    margin: 0,
  });

  const langData = [
    { name: "Erlang", x: 12, y: 97000 },
    { name: "Clojure", x: 11, y: 95000 },
    { name: "Elixir", x: 11, y: 93000 },
    { name: "Perl", x: 19, y: 90000 },
    { name: "Ruby", x: 11, y: 89000 },
    { name: "Scala", x: 9, y: 88000 },
    { name: "Go", x: 9, y: 76000 },
    { name: "Python", x: 9, y: 67000 },
    { name: "JavaScript", x: 10, y: 64000 },
    { name: "PHP", x: 10, y: 49000 },
    { name: "Dart", x: 8, y: 44000 },
    { name: "Prolog", x: 9, y: 43000 },
  ];

  const seriesLang = langData.map(pt => ({
    name: pt.name,
    labels: [pt.name],
    values: [{ x: pt.x, y: pt.y }],
  }));

  slide.addChart(pres.charts.SCATTER, seriesLang, {
    x: 0.5, y: 1.1, w: 9, h: 3.9,
    chartColors: [
      "1E2761", "3B82F6", "60A5FA", "93C5FD", "F59E0B",
      "EF4444", "10B981", "8B5CF6", "EC4899", "14B8A6", "F97316", "64748B"
    ],
    chartArea: { fill: { color: COLORS.cardBg }, roundedCorners: true },
    catAxisLabelColor: COLORS.slate,
    valAxisLabelColor: COLORS.slate,
    valGridLine: { color: "E2E8F0", size: 0.5 },
    catGridLine: { style: "none" },
    showLegend: false,
    lineDataSymbol: "circle",
    lineDataSymbolSize: 10,
    showValue: false,
    catAxisTitle: "Average Years of Experience",
    catAxisTitleFontSize: 10,
    catAxisTitleColor: COLORS.slate,
    valAxisTitle: "Median Salary (USD)",
    valAxisTitleFontSize: 10,
    valAxisTitleColor: COLORS.slate,
    valAxisLabelFormat: "$#,##0",
    title: "Median Salary vs. Experience by Programming Language",
    titleFontSize: 12,
    titleColor: COLORS.slate,
  });

  slide.addText("Reference: figure_3.jpg. Overall reported salary range dropped ~$10K vs. 2023 ($60–75K vs. $70–85K).", {
    x: 0.5, y: 5.05, w: 9, h: 0.25,
    fontSize: 10, fontFace: FONTS.body, color: COLORS.muted,
    align: "left", valign: "middle",
    margin: 0,
  });

  addFooter(slide);
  addSlideNumber(slide, 6);
}

// ============================================================
// SLIDE 7: COMPANY SIZE AND PURCHASING
// ============================================================
{
  const slide = pres.addSlide();
  slide.background = { color: COLORS.lightBg };

  slide.addText("47% Work at Sub-100 Orgs; 62% Influence Tech Purchases", {
    x: 0.5, y: 0.35, w: 9, h: 0.7,
    fontSize: 28, fontFace: FONTS.header, color: COLORS.primary,
    bold: true, align: "left", valign: "middle",
    margin: 0,
  });

  // Left: company size bar chart
  const sizeLabels = ["Freelancer", "2–9", "10–19", "20–99", "100–499", "500–999", "1K–4.9K", "5K–9.9K", "10K+"];
  const sizeValues = [6.1, 10.4, 8.9, 21.2, 18.5, 6.7, 11.0, 3.8, 11.4];

  slide.addChart(pres.charts.BAR, [
    { name: "Share (%)", labels: sizeLabels, values: sizeValues },
  ], {
    x: 0.5, y: 1.2, w: 4.8, h: 3.6,
    barDir: "col",
    chartColors: [COLORS.primary],
    chartArea: { fill: { color: COLORS.cardBg }, roundedCorners: true },
    catAxisLabelColor: COLORS.slate,
    valAxisLabelColor: COLORS.slate,
    valGridLine: { color: "E2E8F0", size: 0.5 },
    catGridLine: { style: "none" },
    showValue: true,
    dataLabelPosition: "outEnd",
    dataLabelColor: COLORS.slate,
    showLegend: false,
    title: "Company Size Distribution (n=42,827)",
    titleFontSize: 11,
    titleColor: COLORS.slate,
    catAxisLabelFontSize: 9,
    valAxisMaxVal: 25,
  });

  // Right: purchasing influence stats
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 5.6, y: 1.3, w: 3.9, h: 1.3,
    fill: { color: COLORS.cardBg },
    shadow: { type: "outer", color: "000000", blur: 6, offset: 2, angle: 135, opacity: 0.08 },
  });
  slide.addText("62%", {
    x: 5.8, y: 1.45, w: 1.5, h: 0.6,
    fontSize: 32, fontFace: FONTS.header, color: COLORS.primary,
    bold: true, align: "left", valign: "middle",
    margin: 0,
  });
  slide.addText("of respondents have influence over technology purchases at their organizations", {
    x: 5.8, y: 2.05, w: 3.5, h: 0.5,
    fontSize: 12, fontFace: FONTS.body, color: COLORS.slate,
    align: "left", valign: "top",
    margin: 0,
  });

  slide.addShape(pres.shapes.RECTANGLE, {
    x: 5.6, y: 2.8, w: 3.9, h: 1.0,
    fill: { color: COLORS.cardBg },
    shadow: { type: "outer", color: "000000", blur: 6, offset: 2, angle: 135, opacity: 0.08 },
  });
  slide.addText("60%", {
    x: 5.8, y: 2.9, w: 1.5, h: 0.5,
    fontSize: 28, fontFace: FONTS.header, color: COLORS.highlight,
    bold: true, align: "left", valign: "middle",
    margin: 0,
  });
  slide.addText("prefer a build-and-buy approach", {
    x: 5.8, y: 3.35, w: 3.5, h: 0.35,
    fontSize: 12, fontFace: FONTS.body, color: COLORS.slate,
    align: "left", valign: "middle",
    margin: 0,
  });

  slide.addShape(pres.shapes.RECTANGLE, {
    x: 5.6, y: 3.95, w: 3.9, h: 1.3,
    fill: { color: COLORS.cardBg },
    shadow: { type: "outer", color: "000000", blur: 6, offset: 2, angle: 135, opacity: 0.08 },
  });
  slide.addText("Top influencers:", {
    x: 5.8, y: 4.05, w: 3.5, h: 0.3,
    fontSize: 12, fontFace: FONTS.header, color: COLORS.slate,
    bold: true, align: "left", valign: "middle",
    margin: 0,
  });
  slide.addText([
    { text: "Senior executives — 99%", options: { bullet: true, breakLine: true, fontSize: 11, color: COLORS.slate } },
    { text: "Engineering managers — 87%", options: { bullet: true, breakLine: true, fontSize: 11, color: COLORS.slate } },
    { text: "Product managers — 77%", options: { bullet: true, fontSize: 11, color: COLORS.slate } },
  ], {
    x: 5.8, y: 4.35, w: 3.5, h: 0.8,
    fontFace: FONTS.body, align: "left", valign: "top",
  });

  addFooter(slide);
